def prefixSuffixString(s1, s2):
    count = 0
    for s in s2:
        found = False
        for s1_str in s1:
            if s1_str.startswith(s) or s1_str.endswith(s):
                found = True
                break
        if found:
            count += 1
    return count

import sys

def main():
    try:
        line1 = sys.stdin.readline()
        while line1 and not line1.strip():
            line1 = sys.stdin.readline()
        if not line1:
            return
        s1 = eval(line1.strip())

        line2 = sys.stdin.readline()
        while line2 and not line2.strip():
            line2 = sys.stdin.readline()
        if not line2:
            return
        s2 = eval(line2.strip())

        result = prefixSuffixString(s1, s2)
        print(result)
    except Exception:
        pass

if __name__ == "__main__":
    main()
